/// <summary>
/// PricingAttribute of table <c>CustDirectDebitMandate</c> field SignatureDate.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustDirectDebitMandateSignatureDate extends UPSPricingAttributeCustDirectDebitMandate implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustDirectDebitMandate, SignatureDate);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::Date);
    CustDirectDebitMandate custDirectDebitMandate;

    while select custDirectDebitMandate
        group by SignatureDate
    {
        if (! ret.in(custDirectDebitMandate.SignatureDate))
        {
            ret.add(custDirectDebitMandate.SignatureDate);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustDirectDebitMandate, SignatureDate));
    qbr.value(queryValue(_value));
}
